    strategies: ['Coordinate instruction with communication, sensory, and physical access specialists.', 'Define a meaningful learning goal and a reliable way to show understanding.', 'Use age-respectful objects, media, and shared activities.', 'Provide sufficient response time without repeatedly changing the prompt.', 'Teach peers how to include the student and communicate directly.', 'Check positioning, fatigue, and equipment access before changing instruction.'],
    accommodations: ['Adapted equipment and AAC access', 'Accessible materials and response methods', 'Health-related breaks per plan', 'Support for movement or positioning as documented'],
    scenarios: ['ELA: Let the student select evidence through accessible switches or AAC.', 'Math: Use accessible objects and a partner-assisted method prescribed by the team.', 'Science: Plan a safe observation or prediction role before a lab begins.', 'Social Studies: Provide accessible choices for comparing historical sources.'],
    misconceptions: ['Two diagnoses do not automatically establish this category.', 'Michigan SMI is not a direct synonym for every federal multiple-disabilities case.', 'Physical assistance should not replace the student’s opportunity to make choices.'], related: ['guided-notes', 'accommodation-checklist', 'visual-schedule'], sldLinks: []
